/**
 * Unit tests for SubLine.intersection.
 */
public class SubLine_intersection_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_BothInside_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (2,2)
        SubLine subLine1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        // Line 2: (0,2) to (2,0)
        SubLine subLine2 = new SubLine(new Vector2D(0, 2), new Vector2D(2, 0));

        // Intersection at (1,1)
        Vector2D result = subLine1.intersection(subLine2, true);

        assertEquals(1.0, result.getX(), EPSILON);
        assertEquals(1.0, result.getY(), EPSILON);
    }














}

